/**
 * The posterior store.
 *
 * A pluggable key-value store of {@link ArmRecord}s keyed by (model, domain), plus a portable JSON
 * snapshot so routing state survives a restart, ships to an edge runtime, or moves between processes.
 * The default is in-process memory. The snapshot decoder validates every field, because a snapshot is a
 * trust boundary: it may come from disk, a database, or another machine.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import type {
  ArmKey,
  ArmRecord,
  BetaPosterior,
  GammaPosterior,
  PosteriorStore,
  StoreSnapshot,
} from '../types.js';

const KEY_SEPARATOR = '�';

function keyOf(model: string, domain: string): string {
  return `${model}${KEY_SEPARATOR}${domain}`;
}

/** An in-process posterior store backed by a Map. */
export class MemoryPosteriorStore implements PosteriorStore {
  private readonly arms = new Map<string, ArmRecord>();

  get(model: string, domain: string): ArmRecord | undefined {
    return this.arms.get(keyOf(model, domain));
  }

  set(record: ArmRecord): void {
    this.arms.set(keyOf(record.model, record.domain), record);
  }

  keys(): ReadonlyArray<ArmKey> {
    return Array.from(this.arms.values(), (record) => ({
      model: record.model,
      domain: record.domain,
    }));
  }

  snapshot(): StoreSnapshot {
    return { version: 1, arms: Array.from(this.arms.values()) };
  }
}

/** Create an in-process posterior store. */
export function createMemoryStore(): PosteriorStore {
  return new MemoryPosteriorStore();
}

/** Serialize a snapshot to a JSON string. */
export function encodeSnapshot(snapshot: StoreSnapshot): string {
  return JSON.stringify(snapshot);
}

/** Replay a snapshot into a store, overwriting any existing records with the same key. */
export function loadSnapshot(store: PosteriorStore, snapshot: StoreSnapshot): void {
  for (const record of snapshot.arms) {
    store.set(record);
  }
}

function asObject(value: unknown, context: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new BayesRouteError('ERR_INVALID_INPUT', `${context} must be an object`);
  }
  return value as Record<string, unknown>;
}

function asNumber(object: Record<string, unknown>, key: string, context: string): number {
  const value = object[key];
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new BayesRouteError('ERR_INVALID_INPUT', `${context}.${key} must be a finite number`);
  }
  return value;
}

function asString(object: Record<string, unknown>, key: string, context: string): string {
  const value = object[key];
  if (typeof value !== 'string') {
    throw new BayesRouteError('ERR_INVALID_INPUT', `${context}.${key} must be a string`);
  }
  return value;
}

function asBeta(value: unknown, context: string): BetaPosterior {
  const object = asObject(value, context);
  return { alpha: asNumber(object, 'alpha', context), beta: asNumber(object, 'beta', context) };
}

function asGamma(value: unknown, context: string): GammaPosterior {
  const object = asObject(value, context);
  return { shape: asNumber(object, 'shape', context), rate: asNumber(object, 'rate', context) };
}

function asArmRecord(value: unknown, index: number): ArmRecord {
  const context = `arms[${index}]`;
  const object = asObject(value, context);
  const posterior = asObject(object.posterior, `${context}.posterior`);
  return {
    model: asString(object, 'model', context),
    domain: asString(object, 'domain', context),
    posterior: {
      quality: asBeta(posterior.quality, `${context}.posterior.quality`),
      latency: asGamma(posterior.latency, `${context}.posterior.latency`),
      cost: asGamma(posterior.cost, `${context}.posterior.cost`),
    },
    pulls: asNumber(object, 'pulls', context),
    accepted: asNumber(object, 'accepted', context),
    rejected: asNumber(object, 'rejected', context),
    lastObservedAt: asNumber(object, 'lastObservedAt', context),
  };
}

/** Parse and validate a snapshot from a JSON string. Throws on any malformed field. */
export function decodeSnapshot(json: string): StoreSnapshot {
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch (error) {
    throw new BayesRouteError('ERR_INVALID_INPUT', `snapshot is not valid JSON: ${String(error)}`);
  }
  const object = asObject(parsed, 'snapshot');
  if (object.version !== 1) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `unsupported snapshot version ${object.version}`,
    );
  }
  const arms = object.arms;
  if (!Array.isArray(arms)) {
    throw new BayesRouteError('ERR_INVALID_INPUT', 'snapshot.arms must be an array');
  }
  return { version: 1, arms: arms.map((arm, index) => asArmRecord(arm, index)) };
}
