/**
 * Node file-backed posterior store.
 *
 * The default store lives in memory, which is enough for one process but loses every accumulated
 * posterior on restart. This adapter persists the whole store to a single JSON file and reloads it on
 * construction, so routing state survives restarts with no database. Writes are atomic: the snapshot is
 * written to a temporary file and renamed over the target, so a crash mid-write never corrupts the
 * store. This is the only entry point that touches a Node built-in (`node:fs`); the rest of BayesRoute
 * stays node-free. For higher throughput or sharing across processes, implement {@link PosteriorStore}
 * over SQLite, Postgres, or Redis instead; this file store is the zero-dependency reference.
 *
 * @packageDocumentation
 */

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import {
  decodeSnapshot,
  encodeSnapshot,
  loadSnapshot,
  MemoryPosteriorStore,
} from '../store/index.js';
import type { ArmKey, ArmRecord, PosteriorStore, StoreSnapshot } from '../types.js';

export type { ArmRecord, PosteriorStore, StoreSnapshot } from '../types.js';

/** Options for {@link createFileStore}. */
export interface FileStoreOptions {
  /** The JSON file path to load from and persist to. */
  readonly path: string;
  /** Pretty-print the persisted JSON. Off by default, for the smallest file. */
  readonly pretty?: boolean;
}

/**
 * Create a posterior store backed by a JSON file. Existing contents are loaded on creation; every write
 * is flushed atomically through a temporary file and a rename.
 *
 * @throws {@link BayesRouteError} with code `ERR_INVALID_INPUT` when the existing file is not a valid
 *   store snapshot.
 */
export function createFileStore(pathOrOptions: string | FileStoreOptions): PosteriorStore {
  const options: FileStoreOptions =
    typeof pathOrOptions === 'string' ? { path: pathOrOptions } : pathOrOptions;
  const { path } = options;
  const memory = new MemoryPosteriorStore();
  if (existsSync(path)) {
    loadSnapshot(memory, decodeSnapshot(readFileSync(path, 'utf8')));
  }

  function persist(): void {
    const directory = dirname(path);
    if (directory.length > 0 && !existsSync(directory)) {
      mkdirSync(directory, { recursive: true });
    }
    const snapshot = memory.snapshot();
    const json = options.pretty ? JSON.stringify(snapshot, null, 2) : encodeSnapshot(snapshot);
    const temporary = `${path}.${process.pid}.tmp`;
    writeFileSync(temporary, json, 'utf8');
    renameSync(temporary, path);
  }

  return {
    get: (model: string, domain: string): ArmRecord | undefined => memory.get(model, domain),
    set: (record: ArmRecord): void => {
      memory.set(record);
      persist();
    },
    keys: (): ReadonlyArray<ArmKey> => memory.keys(),
    snapshot: (): StoreSnapshot => memory.snapshot(),
  };
}
